107:       : status.result === 'stalemate' ? 'Draw by stalemate.' : `Draw (${status.reason.replaceAll('-', ' ')}).`;
108:     opponentTurn.textContent = status.winner === 'b' ? 'VICTORY' : status.winner === 'w' ? 'GAME OVER' : 'DRAW';
109:     yourTurn.textContent = 'GAME OVER';
110:     message.textContent = text;
111:   } else if (botThinking) {
112:     opponentTurn.textContent = 'THINKING…';
113:     yourTurn.textContent = 'BOT THINKING';
114:     message.textContent = `${bots[selectedBot].name} is considering a move…`;
115:   } else if (position.turn === 'b') {
116:     opponentTurn.textContent = 'YOUR MOVE';
