126: function onSquareClick(square) {
127:   const status = currentStatus();
128:   if (botThinking || status.over || position.turn !== 'w' || pendingPromotion) return;
129:   const piece = position.board[square];
130:   if (selectedSquare) {
131:     const candidates = legalMoves(position, selectedSquare).filter(move => move.to === square);
132:     if (candidates.length) {
133:       if (candidates.some(move => move.promotion)) {
134:         showPromotion(candidates);
135:       } else {
136:         playMove(candidates[0]);
137:       }
138:       return;
139:     }
140:   }
141:   selectedSquare = piece?.[0] === 'w' ? square : null;
142:   renderBoard();
143: }
