145: function showPromotion(candidates) {
146:   pendingPromotion = candidates;
147:   const options = $('promotion-options');
148:   options.innerHTML = ['Q', 'R', 'B', 'N'].map(type => {
149:     const move = candidates.find(candidate => candidate.promotion === type);
150:     return `<button type="button" data-promotion="${type}" aria-label="Promote to ${pieceNames[type]}">${pieceGlyphs[`w${type}`]}</button>`;
151:   }).join('');
152:   options.querySelectorAll('[data-promotion]').forEach(button => button.addEventListener('click', () => {
153:     const move = pendingPromotion?.find(candidate => candidate.promotion === button.dataset.promotion);
154:     $('promotion-dialog').hidden = true;
155:     pendingPromotion = null;
156:     if (move) playMove(move);
157:   }));
158:   $('promotion-dialog').hidden = false;
159:   options.querySelector('button')?.focus();
160: }
