162: function playMove(move) {
163:   position = makeMove(position, move);
164:   lastMove = { from: move.from, to: move.to };
165:   history.push({ position, lastMove });
166:   selectedSquare = null;
167:   const status = currentStatus();
168:   renderBoard();
169:   if (!status.over && position.turn === 'b') scheduleBotMove();
170: }
171: 
172: function scheduleBotMove() {
173:   botThinking = true;
174:   const token = ++botTurnToken;
175:   renderBoard();
176:   window.setTimeout(() => {
177:     if (token !== botTurnToken || !botThinking) return;
178:     const move = getBotMove(position, botStrength(bots[selectedBot].rating));
179:     if (token !== botTurnToken) return;
180:     botThinking = false;
181:     if (move) {
182:       position = makeMove(position, move);
183:       lastMove = { from: move.from, to: move.to };
184:       history.push({ position, lastMove });
185:     }
186:     renderBoard();
187:   }, 30);
188: }
189: 
190: function newGame() {
191:   botTurnToken++;
192:   botThinking = false;
193:   pendingPromotion = null;
194:   $('promotion-dialog').hidden = true;
195:   position = createInitialPosition();
196:   history = [{ position, lastMove: null }];
197:   selectedSquare = null;
198:   lastMove = null;
199:   renderBoard();
200: }
201: 
202: function undoMove() {
203:   if (history.length <= 1) return;
204:   botTurnToken++;
205:   botThinking = false;
206:   pendingPromotion = null;
207:   $('promotion-dialog').hidden = true;
208:   // Undo the human move and bot reply together, or the pending human move alone.
209:   const plies = position.turn === 'w' ? 2 : 1;
210:   history.splice(Math.max(1, history.length - plies), plies);
211:   const previous = history[history.length - 1];
212:   position = previous.position;
213:   lastMove = previous.lastMove;
214:   selectedSquare = null;
215:   renderBoard();
216: }
217: 
218: $('undo').addEventListener('click', undoMove);
219: $('flip').addEventListener('click', () => { flipped = !flipped; renderBoard(); });
220: $('restart').addEventListener('click', newGame);
221: renderBots();
222: newGame();

