222:     const notes = check ? [520, 760] : [230];
223:     notes.forEach((frequency, index) => {
224:       const oscillator = audioContext.createOscillator();
225:       const gain = audioContext.createGain();
226:       const start = now + index * 0.11;
227:       oscillator.type = check ? 'triangle' : 'sine';
228:       oscillator.frequency.setValueAtTime(frequency, start);
229:       gain.gain.setValueAtTime(0.0001, start);
230:       gain.gain.exponentialRampToValueAtTime(check ? 0.12 : 0.08, start + 0.012);
231:       gain.gain.exponentialRampToValueAtTime(0.0001, start + (check ? 0.19 : 0.1));
232:       oscillator.connect(gain);
233:       gain.connect(audioContext.destination);
