function principleFor(p, move) {
  const piece = p.board[move.from], type = typeOf(piece), side = colorOf(piece);
  if (Math.abs(coords(move.to)[0] - coords(move.from)[0]) === 2 && type === 'K') return 'King safety: castling';
  if (type === 'P' && ['d4','e4','d5','e5'].includes(move.to)) return 'Fights for the center';
  const homeRank = side === 'w' ? '1' : '8';
  if (['N','B'].includes(type) && move.from[1] === homeRank) return 'Develops a minor piece';
  if (type === 'Q' && p.fullmoveNumber < 8) return 'Consider developing minor pieces before the queen';
  return 'Keep improving piece activity and king safety';
}

