    window.__audioStats = { created: 0, started: 0 };
    const install = () => {
      const proto = window.AudioContext?.prototype;
      if (!proto || proto.__chessWrapped) return;
      const create = proto.createOscillator;
      proto.createOscillator = function () {
        window.__audioStats.created++;
        const osc = create.call(this);
        const start = osc.start.bind(osc);
        osc.start = (...args) => { window.__audioStats.started++; return start(...args); };
        return osc;
      };
      Object.defineProperty(proto, '__chessWrapped', { value: true });
    };
    install();
  });
  await page.goto('http://localhost:3002');
  await page.locator('#sound-toggle').click();
  await page.waitForFunction(() => window.__audioStats.started > 0);
